from rendu import Point
p=Point(4)
p.h('Les menaces priment sur la fréquence')
p.p('La première décision recherche une atteinte générale, rénale, respiratoire, cardiaque, bulbaire ou compartimentale ; le contexte douloureux habituel ne suffit pas à écarter ces complications.', ['e13','p83-myopathies-gravite','p83-boast-loges-0'])
p.p('🚩 Une douleur disproportionnée après un traumatisme et une douleur à la mobilisation passive font suspecter un syndrome des loges ; le diagnostic confirmé impose une décompression immédiate.', ['p83-boast-loges-0','p83-boast-loges-3'])
p.p('🚩 Devant des douleurs des ceintures évoquant une pseudopolyarthrite rhizomélique, une céphalée nouvelle, une claudication mandibulaire ou un trouble visuel changent la priorité : une artérite à cellules géantes doit être recherchée immédiatement.', ['p83-eular26-signes-urgence','p83-eular26-orientation'])
p.p('Si cette artérite est fortement suspectée, les glucocorticoïdes ne doivent pas attendre la confirmation ; les examens diagnostiques sont poursuivis en parallèle.', 'p83-eular26-urgence')
p.p('🚩 Après effort, une anurie, des urines foncées, des signes vitaux anormaux ou un syndrome compartimental motivent une évaluation urgente des complications de rhabdomyolyse.', 'e13')
p.p('🚩 Une faiblesse musculaire avec atteinte respiratoire, cardiaque ou de la déglutition justifie une priorité fondée sur l’organe menacé.', 'p83-myopathies-gravite')
p.h('Comparer les dix diagnostics retenus')
p.tableau(['Diagnostic et signe d’orientation','Examen discriminant et limite','Piège','Conduite','Urgence conditionnelle'],[
 [('DX.1 — Syndrome douloureux myofascial : douleur régionale avec point gâchette.', 'p83-myofascial-fibro'),('La palpation d’une bande tendue reproduit une douleur locale ou propagée.', 'p83-myofascial-fibro'),('Une plainte musculaire localisée ne prouve pas une maladie inflammatoire du muscle.', 'p83-myofascial-fibro'),('L’évaluation clinique oriente une prise en charge multimodale.', 'p83-myofascial-fibro'),('Le tableau local habituel doit être confronté aux autres signes cliniques.', 'p83-phenotype')],
 [('DX.2 — Fibromyalgie : douleurs étendues, sommeil perturbé et fatigue.', 'p83-myofascial-fibro'),('Le diagnostic repose sur une constellation clinique ; les anomalies décrites dans certains sous-groupes ne sont pas des biomarqueurs diagnostiques.', 'p83-myofascial-fibro'),('Une faiblesse, une atrophie ou une anomalie biologique demande une autre explication.', 'p83-myofascial-fibro'),('Éducation, autogestion et activité adaptée participent au traitement individualisé.', ['pa83-fibro-soins','pa83-fibro-activite']),('L’étiquette de douleur chronique ne remplace pas l’examen du patient.', 'p83-myofascial-fibro')],
 [('DX.3 — Courbatures retardées après effort : douleur décalée après charge inhabituelle.', 'doms-mecanisme'),('La chronologie et l’examen dominent ; l’imagerie aide surtout lorsque la présentation reste peu claire.', 'doms-biologie-imagerie'),('Une augmentation d’un marqueur musculaire doit être interprétée avec le tableau clinique.', ['doms-biologie-imagerie','e13']),('La charge est adaptée et la reprise progressive.', ['rms-doms','doms-prevention']),('Des signes rénaux, généraux ou compartimentaux conduisent vers l’évaluation d’une rhabdomyolyse.', 'e13')],
 [('DX.4 — Contusion musculaire traumatique : choc direct, douleur immédiate et hématome.', 'p83-doms-contusion-clinique'),('Comparer les côtés, la contraction et l’étirement ; rechercher une douleur disproportionnée et à l’étirement passif.', ['rms-clinique','p83-boast-loges-0']),('La présence d’un hématome ne suffit pas à expliquer une douleur disproportionnée.', ['p83-doms-contusion-clinique','p83-boast-loges-0']),('Une suspicion de syndrome compartimental impose une évaluation urgente ; sa confirmation impose la chirurgie immédiate.', ['p83-boast-loges-0','p83-boast-loges-3']),('🚩 E2 si un syndrome des loges est suspecté ; la chirurgie ne doit pas attendre lorsque le diagnostic est établi.', 'p83-boast-loges-3')],
 [('DX.5 — Grippe saisonnière : myalgies dans un contexte infectieux respiratoire compatible.', 'p83-grippe'),('Chez l’adulte ambulatoire, la PCR est utile si le résultat modifie la prise en charge ; un test antigénique rapide n’est pas recommandé par la SSI.', 'flu-ssi-tests'),('La stratégie ambulatoire ne doit pas masquer une mauvaise tolérance générale ou respiratoire.', 'flu-ssi-alarmes'),('Évaluer les critères d’hospitalisation avant de poursuivre une démarche ambulatoire.', 'flu-ssi-alarmes'),('Une mauvaise condition générale, une hypoxémie ou une détresse respiratoire changent le lieu des soins.', 'flu-ssi-alarmes')],
 [('DX.6 — Symptômes musculaires associés aux statines : douleur ou faiblesse dans le contexte de l’exposition.', 'p83-statine-frequence'),('La notice Sortis demande de mesurer les CPK devant douleurs, faiblesse ou crampes.', 'aips-sortis-surveillance'),('Une faiblesse progressive persistante avec CK très élevées peut relever d’une myopathie nécrosante immunomédiée.', 'p83-statine-imnm'),('Pour Sortis, arrêter si les CPK dépassent cinq fois la limite supérieure de la normale ; explorer une forme immunomédiée si le tableau la suggère.', ['aips-sortis-surveillance','p83-statine-imnm']),('🚩 E1 lorsque la présentation comporte une rhabdomyolyse avec menace rénale ou métabolique.', 'e13')],
 [('DX.7 — Myopathie hypothyroïdienne : douleurs, crampes ou faiblesse dans un contexte hormonal compatible.', 'p83-hypothyroidie'),('Le bilan thyroïdien et les CK sont interprétés ensemble ; les CK peuvent être normales.', 'p83-hypothyroidie'),('Une CK normale ne suffit pas à exclure une cause hormonale.', 'p83-hypothyroidie'),('L’identification de l’hypothyroïdie oriente le traitement étiologique.', 'p83-hypothyroidie'),('La priorité dépend de l’ensemble des manifestations et des diagnostics concurrents.', 'p83-phenotype')],
 [('DX.8 — Pseudopolyarthrite rhizomélique : douleurs et raideur des ceintures dans le contexte clinique approprié.', 'p83-pmr'),('Le diagnostic combine signes et symptômes ; aucun test unique ne le confirme.', 'p83-eular26-diagnostic'),('Un essai diagnostique de glucocorticoïdes peut faire perdre la fenêtre diagnostique.', 'p83-eular26-pas-test-gc'),('Adresser au spécialiste ; rechercher systématiquement les signes d’artérite à cellules géantes.', ['p83-eular26-orientation','p83-eular26-signes-urgence']),('🚩 E2 si une artérite est suspectée, notamment devant des manifestations crâniennes ou visuelles ; ne pas retarder le traitement d’une forte suspicion.', ['p83-eular26-orientation','p83-eular26-urgence'])],
 [('DX.9 — Rhabdomyolyse d’effort : douleurs, faiblesse ou gonflement après effort avec atteinte biologique musculaire.', 'e12'),('Les CK et leur cinétique s’interprètent avec les symptômes et les complications rénales ou métaboliques.', ['e12','e13']),('Attendre le pic des CK ne répond pas à une menace rénale ou métabolique présente.', ['e12','e13']),('Évaluer la gravité et individualiser les soins selon les complications et les comorbidités.', 'e13'),('🚩 E1 en présence d’une menace rénale ou électrolytique vitale.', 'e13')],
 [('DX.10 — Dermatomyosite : faiblesse proximale associée à des signes cutanés évocateurs.', 'p83-phenotype'),('L’examen clinique oriente les anticorps et les explorations spécialisées, dont la biopsie lorsque nécessaire.', ['pa83-anticorps','pa83-biopsie']),('La douleur seule ne suffit pas à établir une myopathie inflammatoire.', ['p83-myopathies-inflammatoires','p83-phenotype']),('Rechercher l’atteinte d’organes et organiser le bilan spécialisé.', 'p83-myopathies-gravite'),('🚩 E1 si l’atteinte respiratoire, cardiaque ou bulbaire menace immédiatement le patient.', 'p83-myopathies-gravite')]
])
p.fenetre('Trois bifurcations pratiques',[
 ('Douleur après effort : une chronologie retardée et une évolution compatible orientent vers les courbatures ; des urines foncées, une anurie ou des signes généraux anormaux imposent l’évaluation de rhabdomyolyse.', ['doms-mecanisme','e13']),
 ('Douleur des ceintures : la présence de manifestations crâniennes ou visuelles fait rechercher immédiatement une artérite à cellules géantes, même lorsque la plainte initiale semble musculaire.', ['p83-eular26-signes-urgence','p83-eular26-orientation']),
 ('Douleur sous statine : la mesure des CPK participe à la décision médicamenteuse ; une faiblesse progressive ou une dysphagie fait aussi rechercher la voie immunomédiée.', ['aips-sortis-surveillance','p83-statine-imnm'])
])
p.sauver()
